Q: Algorithm find specific cells in binary matrix A: <p>If you already have the separated shapes:</p>
<p>You can call the red cells as the heads. By the picture, they are the top cells wich didn't have a head and are not connected at the left or at the right to a cell marked with 1 that has a head.</p>
<p>In javascript, the code could be like this:</p>
<pre><code>const rows=8;
const cols=8;
let heads=[];

function mark(i,j){
  //put your code for coloring cell row i, col j
}

function hasHead(col){
  let head=0;
  for(let k=0;k&lt;heads.length;k++){
    head=heads[k];
    if(head==col || head==col-1 || head==col+1)
      return 1;
  }
  return 0;
}

function markHeads(m){
  let j0=0;
  for(let i=0;i&lt;rows;i++){
    j=0;
    while(j&lt;cols){
      while(j&lt;cols &amp;&amp; m[i][j]==0)
        j++;
      if(j==cols)
        continue;
      if(hasHead(j)) //left side
        while(j&lt;cols &amp;&amp; m[i][j]==1)
          j++;
      else{
        j0=j;
        while(j&lt;cols &amp;&amp; m[i][j]==1)
          j++;
        if(hasHead(j-1)) //right side
          while(j&lt;cols &amp;&amp; m[i][j]==1)
            j++;
        else
          for(let k=j0;k&lt;j;k++){
            heads.push(k);
            mark(i,k);
          }
      }
    }
  }
}
</code></pre>
